            r={**{k:v for k,v in n.items() if k!='download_url'},'family':'Moonwave','local_path':str(q),'sha256':sh,'dropbox_content_hash':dh,'folder_id':cp,'folder_path':np.rsplit('/',1)[0],'folder_url':home(np.rsplit('/',1)[0]),'image_url':obj['current_native_url'],'verification_method':'FRESH_POSTMOVE_ORIGINAL_DOWNLOAD' if fid in mids else 'PRIOR_ORIGINAL_ACTUAL_BYTES_REHASHED_AGAINST_FRESH_NATIVE_HASH','verified_utc':NOW};rows.append(r);obj.update(sha256=sh,dropbox_content_hash=dh,pre_move_sha256_identical=True,original_verification_method=r['verification_method'])
