    excluded=['execution-seal.json','batch-coordination.json','catalogue-publication-followup.json'];receipts=[{'path':str(q),'size':q.stat().st_size,'sha256':hashlib.sha256(q.read_bytes()).hexdigest()} for q in sorted(ROOT.iterdir()) if q.is_file() and q.name not in excluded]
